import { useEffect, useState } from 'react';
import api from '../services/api';

/** Trae los grupos de opciones/modificadores disponibles (ej: "Tipo de bebida"). */
export default function useModifiers() {
  const [modifiers, setModifiers] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let active = true;
    api
      .get('/modifiers')
      .then((res) => {
        if (active && res.data.status) setModifiers(res.data.data || []);
      })
      .catch((err) => console.error('Error cargando opciones:', err))
      .finally(() => {
        if (active) setLoading(false);
      });
    return () => {
      active = false;
    };
  }, []);

  return { modifiers, loading };
}
